/// Append new key-value pairs to paged KV cache.
#[allow(clippy::too_many_arguments)]
pub unsafe fn append_paged_kv_cache(
    k: *const std::ffi::c_void,
    v: *const std::ffi::c_void,
    k_cache: *mut std::ffi::c_void,
    v_cache: *mut std::ffi::c_void,
    kv_indptr: *const i32,
    kv_indices: *const i32,
    kv_last_page_len: *const i32,
    append_indptr: *const i32,
    batch_size: i32,
    num_kv_heads: i32,
    head_dim: i32,
    page_size: i32,
    dtype: DType,
    kv_layout: KVLayout,
    stream: *mut std::ffi::c_void,
) -> Result<()> {
    let status = flashinfer_append_paged_kv_cache(
        k,
        v,
        k_cache,
        v_cache,
        kv_indptr,
        kv_indices,
        kv_last_page_len,
        append_indptr,
        batch_size,
        num_kv_heads,
        head_dim,
        page_size,
        dtype.into(),
        kv_layout.into(),
        stream,
    );

    check_status(status)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_version() {
        let v = version();
        assert!(!v.is_empty());
    }

    #[test]
    fn test_dtype_conversion() {
        assert_eq!(
            FlashInferDType::from(DType::Float16),
            FlashInferDType::FLASHINFER_DTYPE_FLOAT16
        );
        assert_eq!(
            FlashInferDType::from(DType::BFloat16),
            FlashInferDType::FLASHINFER_DTYPE_BFLOAT16
        );
    }

    #[test]
    fn test_layout_conversion() {
        assert_eq!(
            FlashInferKVLayout::from(KVLayout::HND),
            FlashInferKVLayout::FLASHINFER_KV_LAYOUT_HND
        );
        assert_eq!(
            FlashInferKVLayout::from(KVLayout::NHD),
            FlashInferKVLayout::FLASHINFER_KV_LAYOUT_NHD
        );
    }
}
